tool.command:

  ln -f -s ${input_folder} ${input_folder}_`echo $$`.${input_folder.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

folder_test

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__n__dq__:${properties.n},__dq__file_prefix__dq__:__dq__${properties.file_prefix}__dq____cc____cc__'
  #end if

  #if str($input_folder) != 'None':
    --input_folder ${input_folder}_`echo $$`.${input_folder.ext}
  #end if


  --output_folder $outname_output_folder
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_folder}_`echo $$`.${input_folder.ext};


  if test -f $outname_output_folder; then mv $outname_output_folder $output_folder; fi;
